import XCTest
import Foundation
import CryptoKit
import Darwin
import UploadFoundation
@testable import BackupEngine

private actor GeneratedOriginal:OriginalResourceSource {
 var descriptor:OriginalDescriptor
 let bytes:Int,cloud:Bool,cancel:Bool,change:Bool
 var descriptions=0,requests:[Bool]=[],maximumChunk=0
 init(bytes:Int=100,cloud:Bool=false,cancel:Bool=false,change:Bool=false,descriptor:OriginalDescriptor?=nil){self.bytes=bytes;self.cloud=cloud;self.cancel=cancel;self.change=change;self.descriptor=descriptor ?? OriginalDescriptor(localID:"generated",mediaType:"image",resourceTypes:[1],resourceUTIs:["public.jpeg"],width:1,height:1,creation:Date(timeIntervalSince1970:1),modification:Date(timeIntervalSince1970:2))}
 func describe(_ id:String)->OriginalDescriptor{descriptions+=1;if change && descriptions>1{return OriginalDescriptor(localID:id,mediaType:"image",resourceTypes:[1],resourceUTIs:["public.jpeg"],width:2,height:1,creation:nil,modification:nil)};return descriptor}
 func stream(_ id:String,to:URL,allowNetwork:Bool,progress:@escaping @Sendable(Double)->Void) throws {
  requests.append(allowNetwork);if cloud && !allowNetwork{throw BackupFailure.waitingForOriginal}
  guard FileManager.default.createFile(atPath:to.path,contents:nil,attributes:[.posixPermissions:0o600]) else{throw BackupFailure.storage}
  let handle=try FileHandle(forWritingTo:to);defer{try? handle.close()}
  var left=bytes;let chunk=Data(repeating:0x65,count:65536);while left>0{let count=min(left,chunk.count);maximumChunk=max(maximumChunk,count);try handle.write(contentsOf:chunk.prefix(count));left-=count;progress(Double(bytes-left)/Double(bytes));if cancel{throw CancellationError()}};try handle.synchronize()
 }
}
final class OriginalTests:XCTestCase {
 private func fixture(_ source:GeneratedOriginal) throws -> (OriginalResourcePreparer,BackupItem,ManagedTemporaryFiles,OriginalBinding){let dir=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);addTeardownBlock{try? FileManager.default.removeItem(at:dir)};let files=try ManagedTemporaryFiles(directory:dir),binding=OriginalBinding(accountID:UUID(),deviceID:UUID(),libraryID:UUID());var item=BackupItem(libraryID:binding.libraryID,localAssetIdentifier:"generated",mediaType:"image");item.accountID=binding.accountID;item.deviceID=binding.deviceID;return(OriginalResourcePreparer(source:source,files:files,binding:binding),item,files,binding)}
 func testOrdinaryOriginalProducesCompleteManifest() async throws {let(p,item,files,binding)=try fixture(GeneratedOriginal());let r=try await p.prepare(item,policy:BackupPolicy(),network:NetworkSnapshot());XCTAssertEqual(r.sizeBytes,100);XCTAssertEqual(r.manifest?.binding,binding);XCTAssertEqual(r.manifest?.source.localID,item.localAssetIdentifier);XCTAssertFalse(r.manifest!.cleanupCandidateEvidence);XCTAssertEqual((try FileManager.default.attributesOfItem(atPath:r.fileURL.path)[.posixPermissions] as? NSNumber)?.intValue,0o600);try await p.cleanup(item);XCTAssertFalse(FileManager.default.fileExists(atPath:files.url(item.id).path))}
 func testGenerated20MiBStreamAndHash() async throws {try await performance(20)}
 func testGenerated100MiBStreamAndHash() async throws {try await performance(100)}
 private func performance(_ mib:Int) async throws {let source=GeneratedOriginal(bytes:mib*1024*1024);let(p,item,_,_)=try fixture(source);let start=Date();let r=try await p.prepare(item,policy:BackupPolicy(),network:NetworkSnapshot());var sha=SHA256();let chunk=Data(repeating:0x65,count:65536);for _ in 0..<(mib*16){sha.update(data:chunk)};XCTAssertEqual(r.checksum,sha.finalize().map{String(format:"%02x",$0)}.joined());XCTAssertEqual(r.sizeBytes,mib*1024*1024);let maximum=await source.maximumChunk;XCTAssertLessThanOrEqual(maximum,65536);var usage=rusage();getrusage(RUSAGE_SELF,&usage);print("ACL012 native test process max RSS bytes \(usage.ru_maxrss)");print("ACL012 generated original \(mib) MiB write/hash seconds \(Date().timeIntervalSince(start)); source max chunk \(maximum)")}
 func testICloudRequiresExplicitConsent() async throws {let source=GeneratedOriginal(cloud:true);let(p,item,files,_)=try fixture(source);do{_=try await p.prepare(item,policy:BackupPolicy(),network:NetworkSnapshot());XCTFail()}catch{XCTAssertEqual(error as? BackupFailure,.waitingForOriginal)};XCTAssertFalse(FileManager.default.fileExists(atPath:files.url(item.id).path));let calls=await source.requests;XCTAssertEqual(calls,[false])}
 func testICloudConsentUsesWifiAndRetriesOriginal() async throws {let source=GeneratedOriginal(cloud:true);let(p,item,_,_)=try fixture(source);var policy=BackupPolicy();policy.allowICloudOriginals=true;_=try await p.prepare(item,policy:policy,network:NetworkSnapshot());let calls=await source.requests;XCTAssertEqual(calls,[false,true])}
 func testICloudConsentCannotOverrideCellularOrConstrainedPolicy() async throws {for n in [NetworkSnapshot(cellular:true,wifi:false),NetworkSnapshot(constrained:true),NetworkSnapshot(connected:false)]{let source=GeneratedOriginal(cloud:true);let(p,item,_,_)=try fixture(source);var policy=BackupPolicy();policy.allowICloudOriginals=true;do{_=try await p.prepare(item,policy:policy,network:n);XCTFail()}catch{XCTAssertEqual(error as? BackupFailure,.waitingForOriginal)};let calls=await source.requests;XCTAssertEqual(calls,[false])}}
 func testCancellationRemovesOnlyManagedPartialFile() async throws {let(p,item,files,_)=try fixture(GeneratedOriginal(cancel:true));let neighbor=files.directory.appendingPathComponent("keep");try Data([1]).write(to:neighbor);do{_=try await p.prepare(item,policy:BackupPolicy(),network:NetworkSnapshot());XCTFail()}catch{XCTAssertTrue(error is CancellationError)};XCTAssertFalse(FileManager.default.fileExists(atPath:files.url(item.id).path));XCTAssertTrue(FileManager.default.fileExists(atPath:neighbor.path))}
 func testSourceChangeInvalidatesCapturedEvidence() async throws {let(p,item,files,_)=try fixture(GeneratedOriginal(change:true));do{_=try await p.prepare(item,policy:BackupPolicy(),network:NetworkSnapshot());XCTFail()}catch{XCTAssertEqual(error as? BackupFailure,.sourceChanged)};XCTAssertFalse(FileManager.default.fileExists(atPath:files.url(item.id).path))}
 func testWrongAccountCannotRetrieveOriginal() async throws {let source=GeneratedOriginal();let(p,base,_,_)=try fixture(source);var item=base;item.accountID=UUID();do{_=try await p.prepare(item,policy:BackupPolicy(),network:NetworkSnapshot());XCTFail()}catch{XCTAssertEqual(error as? BackupFailure,.authorization)};let calls=await source.requests;XCTAssertTrue(calls.isEmpty)}
 func testWrongDeviceCannotRetrieveOriginal() async throws {let(p,base,_,_)=try fixture(GeneratedOriginal());var item=base;item.deviceID=UUID();do{_=try await p.prepare(item,policy:BackupPolicy(),network:NetworkSnapshot());XCTFail()}catch{XCTAssertEqual(error as? BackupFailure,.authorization)}}
 func testPartialLivePhotoAndRAWAreUnsupported() {for d in [OriginalDescriptor(localID:"generated",mediaType:"image",resourceTypes:[1,9],resourceUTIs:["public.jpeg","public.movie"],width:1,height:1,creation:nil,modification:nil,livePhoto:true),OriginalDescriptor(localID:"generated",mediaType:"image",resourceTypes:[1],resourceUTIs:["com.adobe.raw-image"],width:1,height:1,creation:nil,modification:nil)]{XCTAssertFalse(d.supported);XCTAssertFalse(OriginalManifest(binding:OriginalBinding(accountID:UUID(),deviceID:UUID(),libraryID:UUID()),source:d,sizeBytes:1,checksum:"a").cleanupCandidateEvidence)}}
 func testEditedMultiResourceOriginalIsUnsupported() {XCTAssertFalse(OriginalDescriptor(localID:"generated",mediaType:"image",resourceTypes:[1,5],resourceUTIs:["public.jpeg","public.jpeg"],width:1,height:1,creation:nil,modification:nil).supported)}
 func testManifestRequiresExactServerIntegrity() async throws {let(p,item,_,_)=try fixture(GeneratedOriginal());let m=try await p.prepare(item,policy:BackupPolicy(),network:NetworkSnapshot()).manifest!;let id=UUID(),v=UUID();XCTAssertTrue(m.matches(OriginalServerProof(id:id,mediaType:"image",sizeBytes:100,checksum:m.checksum,verificationId:v)));for proof in [OriginalServerProof(id:id,status:"UPLOADED",mediaType:"image",sizeBytes:100,checksum:m.checksum,verificationId:v),OriginalServerProof(id:id,mediaType:"image",sizeBytes:99,checksum:m.checksum,verificationId:v),OriginalServerProof(id:id,mediaType:"image",sizeBytes:100,checksum:"0",verificationId:v)]{XCTAssertFalse(m.matches(proof))}}
 func testManifestCannotBeRemovedFromDurableQueue() async throws {let(p,base,files,_)=try fixture(GeneratedOriginal());let q=try SQLiteBackupQueue(url:files.directory.appendingPathComponent("queue.sqlite"));_=try await q.enqueue(base);let r=try await p.prepare(base,policy:BackupPolicy(),network:NetworkSnapshot());var item=base;item.state = .preparing;item.expectedSizeBytes=r.sizeBytes;item.expectedChecksum=r.checksum;item.originalManifest=r.manifest;item=try await q.save(item);item.originalManifest=nil;do{_=try await q.save(item);XCTFail()}catch{XCTAssertEqual(error as? BackupFailure,.illegalTransition)}}
 func testManifestSurvivesQueueReopen() async throws {let(p,base,files,_)=try fixture(GeneratedOriginal());let url=files.directory.appendingPathComponent("queue.sqlite");let q=try SQLiteBackupQueue(url:url);_=try await q.enqueue(base);let r=try await p.prepare(base,policy:BackupPolicy(),network:NetworkSnapshot());var item=base;item.state = .preparing;item.expectedSizeBytes=r.sizeBytes;item.expectedChecksum=r.checksum;item.originalManifest=r.manifest;_=try await q.save(item);let reopened=try SQLiteBackupQueue(url:url),record=try await reopened.read(item.id);XCTAssertEqual(record?.originalManifest,r.manifest)}
 func testNativeBoundRecordCannotUseLegacyProtectionProof() async throws {let(_,base,files,_)=try fixture(GeneratedOriginal());let q=try SQLiteBackupQueue(url:files.directory.appendingPathComponent("queue.sqlite"));_=try await q.enqueue(base);var item=base;item.state = .protected;item.assetID=UUID();item.expectedSizeBytes=100;let proof=try JSONDecoder().decode(ServerAsset.self,from:JSONSerialization.data(withJSONObject:["id":item.assetID!.uuidString,"mediaType":"image","status":"PROTECTED","sizeBytes":100]));do{_=try await q.protect(item,proof:proof);XCTFail()}catch{XCTAssertEqual(error as? BackupFailure,.illegalTransition)}}
}
